INSERT INTO "public"."jagiellonia_questions" ("id", "difficulty", "question", "options", "correct_index") VALUES (1, 'easy', 'W jakich barwach gra drużyna Jagiellonii Białystok?', '["Biało-niebieskie","Żółto-czerwone","Zielono-białe","Bordowo-granatowe"]', 1), (2, 'easy', 'Jaką nazwę nosi stadion, na którym Jagiellonia rozgrywa swoje mecze domowe?', '["Stadion Śląski","Chorten Arena (Stadion Miejski)","Stadion Wojska Polskiego","Tarczyński Arena"]', 1), (3, 'easy', 'Który przydomek najczęściej przypisuje się drużynie Jagiellonii?', '["Kolejorz","Duma Podlasia","Biała Gwiazda","Wojskowi"]', 1), (4, 'medium', 'Pod wodzą jakiego trenera Jagiellonia zdobyła swój pierwszy historyczny Puchar Polski w 2010 roku?', '["Michał Probierz","Czesław Michniewicz","Adam Nawałka","Ireneusz Mamrot"]', 0), (5, 'medium', 'Podaj nazwisko trenera, który doprowadził Jagiellonię do sensacyjnego Mistrzostwa Polski w 2024 roku.', '["Piotr Stokowiec","Adrian Siemieniec","Maciej Stolarczyk","Bogdan Zając"]', 1), (6, 'hard', 'Podaj dokładną datę (rok) oficjalnego powstania pierwowzoru klubu jako Koła Sportowego Pożarnik w Białymstoku.', '["1920 rok","1924 rok","1930 rok","1945 rok"]', 0), (7, 'hard', 'Który zawodnik Jagiellonii jako pierwszy w historii klubu zagrał w reprezentacji Polski seniorów?', '["Jacek Bayer (1987)","Tomasz Frankowski","Marek Citko","Grzegorz Sandomierski"]', 0);